// Differential tests of py-codecs against CPython (fixture generated by
// tools/fixtures/generate_codec_cases.py), plus time bounds for large input.

import { readFileSync } from 'node:fs';

import { describe, expect, it, vi } from 'vitest';

import { parseEmail } from './email';
import { type CodecErrors, pyDecode, pyEncode } from './py-codecs';

type Outcome = string | { error: string };
type Case = [string, string, Outcome, Outcome, Outcome, Outcome, Outcome];

const HANDLERS: readonly CodecErrors[] = [
  'strict',
  'replace',
  'ignore',
  'backslashreplace',
  'surrogateescape',
];

const CASES = JSON.parse(
  readFileSync(new URL('__fixtures__/py-codecs.json', import.meta.url), 'utf8'),
) as Case[];

function fromHex(hex: string): Uint8Array {
  return Uint8Array.from(hex.match(/../gu) ?? [], byte =>
    Number.parseInt(byte, 16),
  );
}

function decodeOutcome(
  bytes: Uint8Array,
  codec: string,
  errors: CodecErrors,
): Outcome {
  try {
    return pyDecode(bytes, codec, errors);
  } catch (error) {
    return { error: (error as Error).message };
  }
}

describe('pyDecode matches CPython', () => {
  it.each(CASES.map(item => [`${item[0]}:${item[1]}`, item] as const))(
    '%s',
    (_, item) => {
      const [codec, hex, ...expected] = item;
      const bytes = fromHex(hex);
      const actual = HANDLERS.map(errors =>
        decodeOutcome(bytes, codec, errors),
      );
      expect(actual).toEqual(expected);
    },
  );
});

// Generous bounds (CPython takes well under 0.5 s for each): they catch a
// return to per-character string building, which took 2-30 s.
const TIME_LIMIT_MS = 3000;
// CPU time of this test process (best of a few runs), so a busy machine
// (parallel test workers, other jobs) doesn't make the bounds flaky; the
// old code was slow on every run.
const RUNS = 2;
// Large inputs on a loaded machine can take a while.
const LARGE_TIMEOUT_MS = 120_000;
const CLEARLY_FAST_MS = 300;

/** Milliseconds of CPU time this process has used. */
function cpuMs(): number {
  const { user, system } = process.cpuUsage();
  return (user + system) / 1000;
}

function timed(action: () => unknown): number {
  let best = Number.POSITIVE_INFINITY;
  for (let run = 0; run < RUNS && best > CLEARLY_FAST_MS; run += 1) {
    const start = cpuMs();
    action();
    best = Math.min(best, cpuMs() - start);
  }
  return best;
}

async function timedAsync(action: () => Promise<unknown>): Promise<number> {
  let best = Number.POSITIVE_INFINITY;
  for (let run = 0; run < RUNS && best > CLEARLY_FAST_MS; run += 1) {
    const start = cpuMs();
    // oxlint-disable-next-line no-await-in-loop -- runs must not overlap
    await action();
    best = Math.min(best, cpuMs() - start);
  }
  return best;
}

describe('large input', () => {
  it('does not cost every short decode a large buffer', () => {
    // 128 KiB per encoded word: 4 million in 50 MiB of headers.
    const word = Uint8Array.of(0x61);
    const start = process.cpuUsage();
    for (let index = 0; index < 200_000; index += 1) {
      pyDecode(word, index % 2 === 0 ? 'big5' : 'gbk');
    }
    const { user, system } = process.cpuUsage(start);
    expect((user + system) / 1000).toBeLessThan(4000);
  });

  it('keeps text longer than the initial buffer', () => {
    const text = 'a'.repeat(300);
    expect(pyDecode(new TextEncoder().encode(text), 'big5')).toBe(text);
  });

  it('drops redundant iso-2022-jp escapes in one copy', () => {
    // A number per byte: 8 times the size of the input.
    const from = vi.spyOn(Uint8Array, 'from');
    const escape = [0x1b, 0x24, 0x42];
    const bytes = Uint8Array.of(
      ...escape,
      ...escape,
      0x24,
      0x22,
      0x1b,
      0x28,
      0x42,
    );
    const text = pyDecode(bytes, 'iso2022_jp_2');
    expect(from).not.toHaveBeenCalled();
    from.mockRestore();
    expect(text).toBe('\u3042');
  });

  it(
    'decodes 8 MB of big5, gbk and euc_kr quickly',
    () => {
      const size = 8_000_000;
      const text = new Uint8Array(size);
      for (let index = 0; index < size; index += 2) {
        text[index] = 0xa4;
        text[index + 1] = 0xa1 + ((index / 2) % 90);
      }
      for (const codec of ['big5', 'gbk', 'euc_kr']) {
        expect(timed(() => pyDecode(text, codec, 'replace'))).toBeLessThan(
          TIME_LIMIT_MS,
        );
      }
      const invalid = new Uint8Array(size).fill(0xff);
      expect(timed(() => pyDecode(invalid, 'big5', 'replace'))).toBeLessThan(
        TIME_LIMIT_MS,
      );
    },
    LARGE_TIMEOUT_MS,
  );

  it(
    'decodes and encodes 30 MB of ASCII, Latin-1 and UTF-8 quickly',
    () => {
      // CPython: under 0.1 s each; the per-character encoders took 5 s.
      const size = 30_000_000;
      const bytes = new Uint8Array(size).fill(0x41);
      const latin = new Uint8Array(size).fill(0xe9);
      for (const codec of ['ascii', 'latin-1', 'utf-8', 'cp1252']) {
        expect(timed(() => pyDecode(bytes, codec))).toBeLessThan(TIME_LIMIT_MS);
      }
      expect(timed(() => pyDecode(latin, 'latin-1'))).toBeLessThan(
        TIME_LIMIT_MS,
      );
      expect(timed(() => pyDecode(latin, 'cp1252'))).toBeLessThan(
        TIME_LIMIT_MS,
      );
      const text = 'A'.repeat(size);
      for (const codec of ['ascii', 'latin-1', 'utf-8']) {
        expect(timed(() => pyEncode(text, codec))).toBeLessThan(TIME_LIMIT_MS);
      }
      const accented = 'é'.repeat(size);
      expect(timed(() => pyEncode(accented, 'latin-1'))).toBeLessThan(
        TIME_LIMIT_MS,
      );
      // Error handlers run per character, like CPython's.
      const halfLatin = latin.subarray(0, size / 2);
      expect(timed(() => pyDecode(halfLatin, 'utf-8', 'replace'))).toBeLessThan(
        TIME_LIMIT_MS,
      );
      expect(
        timed(() => pyEncode(accented.slice(0, size / 2), 'ascii', 'replace')),
      ).toBeLessThan(TIME_LIMIT_MS);
    },
    LARGE_TIMEOUT_MS,
  );

  // CPython's parse_email takes ~1.3 s and ~0.6 s for these; tsdmarc took
  // 16 s and ~7 s before decoding went through fast paths.
  it(
    'parses an email with a 15 MB base64 attachment quickly',
    async () => {
      const payload = new Uint8Array(15_000_000);
      for (let index = 0; index < payload.length; index += 1) {
        payload[index] = (index * 7919) & 0xff;
      }
      const base64 = Buffer.from(payload)
        .toString('base64')
        .replaceAll(/(.{76})/gu, '$1\n');
      const message = `From: a@b.c\nSubject: x\nContent-Type: multipart/mixed; boundary=B\n\n--B\nContent-Type: application/zip; name=a.zip\nContent-Transfer-Encoding: base64\n\n${base64}\n--B--\n`;
      const bytes = new TextEncoder().encode(message);
      let attachments = 0;
      const parse = async (): Promise<void> => {
        attachments = (await parseEmail(bytes)).attachments.length;
      };
      expect(await timedAsync(parse)).toBeLessThan(TIME_LIMIT_MS * 2);
      expect(attachments).toBe(1);
    },
    LARGE_TIMEOUT_MS,
  );

  it(
    'parses an email with a 27 MB quoted-printable attachment quickly',
    async () => {
      const body = `${'=41'.repeat(25)}=\n`.repeat(360_000);
      const message = `From: a@b.c\nSubject: x\nContent-Type: multipart/mixed; boundary=B\n\n--B\nContent-Type: text/plain\nContent-Disposition: attachment; filename=a.txt\nContent-Transfer-Encoding: quoted-printable\n\n${body}\n--B--\n`;
      const bytes = new TextEncoder().encode(message);
      let attachments = 0;
      const parse = async (): Promise<void> => {
        attachments = (await parseEmail(bytes)).attachments.length;
      };
      expect(await timedAsync(parse)).toBeLessThan(TIME_LIMIT_MS * 2);
      expect(attachments).toBe(1);
    },
    LARGE_TIMEOUT_MS,
  );
});

describe('pyEncode', () => {
  it('reports positions in code points like Python', () => {
    expect(() => pyEncode('a\u{1f600}bé', 'ascii')).toThrow(
      "'ascii' codec can't encode character '\\U0001f600' in position 1: ordinal not in range(128)",
    );
    expect(() => pyEncode('\u{1f600}éé!', 'latin-1')).toThrow(
      "'latin-1' codec can't encode character '\\U0001f600' in position 0: ordinal not in range(256)",
    );
    expect(() => pyEncode('aéé', 'ascii')).toThrow(
      "'ascii' codec can't encode characters in position 1-2: ordinal not in range(128)",
    );
    expect(() => pyEncode('a\u{1f600}\ud800', 'utf-8')).toThrow(
      "'utf-8' codec can't encode character '\\ud800' in position 2: surrogates not allowed",
    );
  });

  it('applies the error handlers like Python', () => {
    const hex = (bytes: Uint8Array): string =>
      Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join('');
    expect(hex(pyEncode('a\udce9b', 'ascii', 'surrogateescape'))).toBe(
      '61e962',
    );
    expect(() =>
      pyEncode('a\udce9é\u{1f600}', 'ascii', 'surrogateescape'),
    ).toThrow(
      "'ascii' codec can't encode characters in position 2-3: ordinal not in range(128)",
    );
    expect(hex(pyEncode('aé\u{1f600}b', 'ascii', 'replace'))).toBe('613f3f62');
    expect(hex(pyEncode('aé\u{1f600}b', 'ascii', 'ignore'))).toBe('6162');
    expect(hex(pyEncode('aé\u{1f600}', 'latin-1', 'backslashreplace'))).toBe(
      '61e95c553030303166363030',
    );
    expect(hex(pyEncode('a\udce9b', 'utf-8', 'surrogateescape'))).toBe(
      '61e962',
    );
    expect(() =>
      pyEncode('a\udce9\ud800b', 'utf-8', 'surrogateescape'),
    ).toThrow(
      "'utf-8' codec can't encode character '\\ud800' in position 2: surrogates not allowed",
    );
    expect(hex(pyEncode('a\ud800b', 'utf-8', 'replace'))).toBe('613f62');
    expect(hex(pyEncode('a\ud800b', 'utf-8', 'backslashreplace'))).toBe(
      '615c756438303062',
    );
  });
});

describe('TextBuilder', () => {
  it('costs a short decode its length, not a 64 Ki buffer', () => {
    // A 1 MiB Subject of `=?hz?q?a?=` words took 4.7 s: 128 KiB per word.
    const byte = Uint8Array.of(0x61);
    const start = process.cpuUsage();
    for (let round = 0; round < 100_000; round += 1) {
      pyDecode(byte, 'hz');
      pyDecode(byte, 'utf-16-le', 'replace');
    }
    const { user, system } = process.cpuUsage(start);
    // About 0.9 s now, about 9 s with a 64 Ki buffer per decode.
    expect((user + system) / 1000).toBeLessThan(3000);
  });

  it('keeps every unit as its buffer grows and flushes', () => {
    for (const length of [31, 32, 33, 64, 65, 0xff_ff, 0x1_00_00, 0x1_00_01]) {
      const text = 'é中'.repeat(length).slice(0, length);
      const bytes = Buffer.from(text, 'utf16le');
      expect(pyDecode(bytes, 'utf-16-le')).toBe(text);
    }
  });
});
